import sys
from itertools import groupby

def main():
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()

    max_beauty = 0
    left = 0
    count_a = 0
    count_b = 0

    for right in range(n):
        if s[right] == 'a':
            count_a += 1
        else:
            count_b += 1

        while min(count_a, count_b) > k:
            if s[left] == 'a':
                count_a -= 1
            else:
                count_b -= 1
            left += 1

        current_length = right - left + 1
        max_beauty = max(max_beauty, current_length)

    print(max_beauty)

if __name__ == "__main__":
    main()
